# area: descriptors_properties
# hypothesis: A plain function with no self, defined in the class body and used as a decorator on __set__, is ordinary code at runtime, so a checker should still treat __set__ as a data-descriptor method and type h.attr = 5 accordingly.
from typing import reveal_type


class Desc:
    def wrap(fn):
        return fn

    def __init__(self) -> None:
        self.value = 0

    def __get__(self, obj: object, owner: type | None = None) -> int:
        return self.value

    @wrap
    def __set__(self, obj: object, value: int) -> None:
        self.value = value

    def __delete__(self, obj: object) -> None:
        self.value = -1


class Host:
    attr = Desc()


h = Host()
reveal_type(h.attr)
print(h.attr)
h.attr = 5
print(h.attr)
del h.attr
print(h.attr)
